const base = $json;
if (!base.ready) return { json: base };

const body = base.context;
const urls = [];
const blockedHost = (host) => host === 'dataforseo.com' || host.endsWith('.dataforseo.com');
const add = (value) => {
  if (typeof value !== 'string') return;
  const trimmed = value.trim();
  const candidates = /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(trimmed)
    ? ['https://' + trimmed + '/']
    : (trimmed.match(/https:\/\/[^\s"'<>]+/gi) || []);
  for (let candidate of candidates) {
    candidate = candidate.replace(/[),.;]+$/, '');
    try {
      const parsed = new URL(candidate);
      const host = parsed.hostname.toLowerCase().replace(/^www\./, '');
      if (
        parsed.protocol !== 'https:' ||
        parsed.username ||
        parsed.password ||
        parsed.port ||
        !host.includes('.') ||
        blockedHost(host)
      ) continue;
      parsed.hash = '';
      const clean = parsed.toString();
      if (!urls.includes(clean)) urls.push(clean);
    } catch {}
  }
};
const addRecord = (value) => {
  if (typeof value === 'string') return add(value);
  if (!value || typeof value !== 'object') return;
  add(value.url);
  add(value.website);
  add(value.domain);
};
const topic = String(body.job.requestedTopic || body.job.primaryKeyword);
const tokens = new Set(
  topic.toLowerCase().split(/[^a-z0-9]+/).filter(
    (token) => token.length > 2 &&
      !['what', 'which', 'where', 'when', 'with', 'this', 'that', 'simple', 'terms', 'guide'].includes(token),
  ),
);
const matched = (value) => {
  const text = [
    value?.query,
    value?.keyword,
    value?.title,
    value?.description,
  ].filter((entry) => typeof entry === 'string').join(' ').toLowerCase();
  const shared = [...tokens].filter((token) => text.includes(token)).length;
  return shared / Math.max(1, tokens.size) >= 0.6;
};

add('https://' + body.job.domain + '/');

for (const value of body.job.input?.sourceUrls ?? []) add(value);
for (const value of base.liveSerpUrls ?? []) add(value);

const research = body.brief?.research ?? body.snapshot ?? {};
for (const value of research.serpEvidence ?? []) {
  if (matched(value)) addRecord(value);
}
// Research provenance may include provider API endpoints. Only an explicit,
// public page URL is eligible, and DataForSEO hosts are always excluded.
for (const value of research.sources ?? []) {
  if (matched(value)) add(value?.url);
}

const competitorGroups = [
  research.seoCompetitors,
  research.competitors?.direct,
  research.competitors?.seo,
  research.competitors?.adjacent,
  body.snapshot?.seoCompetitors,
  body.memory?.competitors?.direct,
  body.memory?.competitors?.seo,
  body.memory?.competitors?.adjacent,
  research.offeringProfile?.directCompetitors,
  research.offeringProfile?.adjacentOrganisations,
  body.snapshot?.offeringProfile?.directCompetitors,
  body.snapshot?.offeringProfile?.adjacentOrganisations,
];
for (const group of competitorGroups) {
  for (const value of Array.isArray(group) ? group : []) addRecord(value);
}
const notes = [
  body.job.input?.goal,
  body.job.input?.price ? 'PRICE GUIDANCE: ' + body.job.input.price : '',
  body.job.input?.boundaries ? 'BUSINESS LIMITS: ' + body.job.input.boundaries : '',
].filter(Boolean).join('\n');
const context = {
  ...body,
  snapshot: body.snapshot ?? {
    offeringProfile: research.offeringProfile ?? {},
    selectedKeywords: research.selectedKeywords ?? [],
    keywordCandidates: research.keywordCandidates ?? [],
    seoCompetitors: research.seoCompetitors ?? [],
    serpEvidence: research.serpEvidence ?? [],
    warnings: research.warnings ?? [],
  },
  memory: body.memory ?? {
    companyOverview: research.companyOverview ?? '',
    profile: research.profile ?? {},
    competitors: research.competitors ?? { direct: [], seo: [], adjacent: [] },
    keywordCandidates: research.keywordCandidates ?? [],
    sources: research.sources ?? [],
    warnings: research.warnings ?? [],
  },
  profile: {
    ...(body.profile ?? {}),
    tone: body.job.input?.voice ?? body.profile?.voice ?? body.profile?.tone ?? '',
    sells: body.job.input?.offer ?? body.profile?.offer ?? body.profile?.sells ?? '',
  },
  job: {
    ...body.job,
    input: { ...body.job.input, goal: notes },
  },
};
return {
  json: {
    sessionId: base.sessionId,
    jobId: base.jobId,
    ready: urls.length > 0,
    context,
    strategy: base.strategy,
    urls: urls.slice(0, 12),
    failure: urls.length
      ? null
      : {
          code: 'ARTICLE_SOURCES_MISSING',
          message: 'No topic-matched public pages were available to check.',
        },
  },
};

const base = $('Prepare Grounded Draft').first().json;
const status = Number($json.statusCode ?? 0);
const body = $json.body ?? $json.data ?? {};
const blocks = Array.isArray(body.content) ? body.content : [];
const draft = blocks.find((block) => block?.type === 'tool_use' && block?.name === 'save_seo_article')?.input;
if (status < 200 || status >= 300 || body.stop_reason === 'max_tokens' || !draft || typeof draft !== 'object') {
  return {
    json: {
      ...base,
      valid: false,
      failure: {
        code: 'ARTICLE_DRAFT_FAILED',
        message: 'The writing model did not return a complete draft, so nothing was saved.',
      },
    },
  };
}

const normalise = (value) => String(value ?? '')
  .normalize('NFKC')
  .replace(/!\[([^\]]*)\]\([^\n)]*\)/g, '$1')
  .replace(/\[([^\]]+)\]\([^\n)]*\)/g, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/^\s{0,3}(?:#{1,6}|>)\s*/gm, '')
  .replace(/^\s*[-+]\s+/gm, '')
  .replace(/[`*_~]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const contains = (haystack, needle) => {
  const wanted = normalise(needle);
  return wanted.length > 0 && normalise(haystack).includes(wanted);
};
const normaliseExcerpt = (value) => String(value ?? '')
  .normalize('NFKC')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const containsExcerpt = (haystack, needle) => {
  const wanted = normaliseExcerpt(needle);
  if (wanted.length > 0 && normaliseExcerpt(haystack).includes(wanted)) return true;
  const compact = (value) => normaliseExcerpt(value).replace(/\s+/g, '');
  const compactWanted = compact(needle);
  return compactWanted.length > 0 && compact(haystack).includes(compactWanted);
};
const visibleExcerpt = (value) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, 280);
const collect = (value, output = []) => {
  if (typeof value === 'string') output.push(value);
  else if (Array.isArray(value)) for (const entry of value) collect(entry, output);
  else if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) collect(entry, output);
  }
  return output;
};
const clampAtWord = (value, maximum) => {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (text.length <= maximum) return text;
  const candidate = text.slice(0, maximum + 1);
  const boundary = candidate.lastIndexOf(' ');
  return candidate.slice(0, boundary >= Math.floor(maximum * 0.6) ? boundary : maximum)
    .replace(/[,:;\-\s]+$/, '')
    .trim();
};
const faqData = (faq) => faq.length
  ? {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: faq.map((item) => ({
        '@type': 'Question',
        name: item.question,
        acceptedAnswer: { '@type': 'Answer', text: item.answer },
      })),
    }
  : [];

const pageById = new Map(base.pages.map((page) => [page.id, page]));
const sources = Array.isArray(draft.sources) ? draft.sources : [];
const claims = Array.isArray(draft.claims) ? draft.claims : [];
const repairReasons = [];
if (sources.length < 4) repairReasons.push('Keep at least four verified source records.');
for (const source of sources) {
  const page = pageById.get(source?.id);
  if (!page || source?.url !== page.url) {
    repairReasons.push('Every source ID and URL must match one of the verified pages.');
    break;
  }
}
const sanitizedSources = sources.map((source) => {
  const page = pageById.get(source?.id);
  return {
    ...source,
    title: String(source?.title || page?.title || ''),
    excerpt:
      typeof source?.excerpt === 'string' && page && containsExcerpt(page.text, source.excerpt)
        ? source.excerpt
        : visibleExcerpt(page?.text),
  };
});
const assembled = collect({ ...draft, claims: undefined, sources: undefined }).join('\0');
for (const claim of claims) {
  const ids = Array.isArray(claim?.sourceIds) ? claim.sourceIds : [];
  const excerpts = Array.isArray(claim?.excerpts) ? claim.excerpts : [];
  if (typeof claim?.sentence !== 'string' || !contains(assembled, claim.sentence)) {
    repairReasons.push('Every claim-ledger sentence must appear in the visible article text.');
  }
  if (claim?.support === 'unsupported') {
    repairReasons.push('Remove every unsupported claim or replace it with supported wording.');
  }
  if (!ids.length || !excerpts.length) {
    repairReasons.push('Every claim needs a source ID and a short exact excerpt.');
  }
  if (ids.some((id) => !pageById.has(id))) {
    repairReasons.push('Every claim source ID must refer to a verified page.');
  }
  if (
    excerpts.some(
      (excerpt) =>
        typeof excerpt !== 'string' ||
        !ids.some((id) => containsExcerpt(pageById.get(id)?.text, excerpt)),
    )
  ) {
    repairReasons.push('Every claim excerpt must occur on one of its cited verified pages.');
  }
}

const rawFaq = Array.isArray(draft.faq) ? draft.faq : [];
const faq = rawFaq
  .filter(
    (item) =>
      item &&
      typeof item === 'object' &&
      typeof item.question === 'string' &&
      typeof item.answer === 'string',
  )
  .map((item) => ({ question: item.question, answer: item.answer }));
if (!Array.isArray(draft.faq) || faq.length !== rawFaq.length) {
  repairReasons.push('Every FAQ entry must have a text question and answer.');
}
const originalTitle = String(draft.seoTitle ?? '').replace(/\s+/g, ' ').trim();
const originalMeta = String(draft.metaDescription ?? '').replace(/\s+/g, ' ').trim();
const seoTitle = clampAtWord(originalTitle, 65);
const metaDescription = clampAtWord(originalMeta, 165);
const warnings = Array.isArray(draft.warnings) ? [...draft.warnings] : [];
if (seoTitle !== originalTitle) warnings.push('The SEO title was shortened to 65 characters or fewer.');
if (metaDescription !== originalMeta) warnings.push('The meta description was shortened to 165 characters or fewer.');
const hasPartialClaim = claims.some((claim) => claim?.support === 'partial');
if (hasPartialClaim && draft.status === 'completed') {
  warnings.push('The draft is marked partial because at least one retained claim is only partially supported.');
}
const sanitizedDraft = {
  ...draft,
  status: hasPartialClaim && draft.status === 'completed' ? 'partial' : draft.status,
  seoTitle,
  metaDescription,
  faq,
  structuredData: {
    ...(draft.structuredData && typeof draft.structuredData === 'object' ? draft.structuredData : {}),
    faqPage: faqData(faq),
  },
  sources: sanitizedSources,
  claims,
  warnings: [...new Set(warnings)],
};
const reasons = [...new Set(repairReasons)];
return {
  json: {
    ...base,
    valid: true,
    draft: sanitizedDraft,
    needsRepair: reasons.length > 0,
    repairReasons: reasons,
    validationBody: {
      sessionId: base.sessionId,
      jobId: base.jobId,
      result: { ...sanitizedDraft, model: 'claude-sonnet-4-6' },
    },
  },
};

const request = JSON.parse(JSON.stringify($json.requestBody));
request.temperature = 0;
const reasons = Array.isArray($json.repairReasons) ? $json.repairReasons : [];
request.messages = [{
  role: 'user',
  content: [
    'Repair this draft once. Fix every listed issue, remove or qualify unsupported claims, and keep the requested topic and full article contract.',
    'SEO titles must be 20–65 characters. Meta descriptions must be 70–165 characters. Every risky date, statistic, quote, or attribution needs a matching claim-ledger row. Visible FAQ items and FAQPage data must match exactly.',
    'REQUIRED FIXES:',
    reasons.length ? reasons.map((reason, index) => String(index + 1) + '. ' + reason).join('\n') : '1. Recheck grounding and final quality.',
    'DRAFT:',
    JSON.stringify($json.draft),
    'VERIFIED SOURCES:',
    JSON.stringify($json.pages),
  ].join('\n'),
}];
return { json: { ...$json, requestBody: request } };

const base = $('Prepare One Repair').first().json;
const status = Number($json.statusCode ?? 0);
const body = $json.body ?? $json.data ?? {};
const draft = (Array.isArray(body.content) ? body.content : [])
  .find((block) => block?.type === 'tool_use' && block?.name === 'save_seo_article')?.input;
if (status < 200 || status >= 300 || body.stop_reason === 'max_tokens' || !draft || typeof draft !== 'object') {
  return {
    json: {
      ...base,
      valid: false,
      failure: {
        code: 'ARTICLE_REPAIR_INCOMPLETE',
        message: 'The writing model returned an incomplete repair, so the draft was not saved.',
      },
    },
  };
}

const normalise = (value) => String(value ?? '')
  .normalize('NFKC')
  .replace(/!\[([^\]]*)\]\([^\n)]*\)/g, '$1')
  .replace(/\[([^\]]+)\]\([^\n)]*\)/g, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/^\s{0,3}(?:#{1,6}|>)\s*/gm, '')
  .replace(/^\s*[-+]\s+/gm, '')
  .replace(/[`*_~]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const contains = (haystack, needle) => {
  const wanted = normalise(needle);
  return wanted.length > 0 && normalise(haystack).includes(wanted);
};
const normaliseExcerpt = (value) => String(value ?? '')
  .normalize('NFKC')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const containsExcerpt = (haystack, needle) => {
  const wanted = normaliseExcerpt(needle);
  if (wanted.length > 0 && normaliseExcerpt(haystack).includes(wanted)) return true;
  const compact = (value) => normaliseExcerpt(value).replace(/\s+/g, '');
  const compactWanted = compact(needle);
  return compactWanted.length > 0 && compact(haystack).includes(compactWanted);
};
const visibleExcerpt = (value) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, 280);
const collect = (value, output = []) => {
  if (typeof value === 'string') output.push(value);
  else if (Array.isArray(value)) for (const entry of value) collect(entry, output);
  else if (value && typeof value === 'object') {
    for (const entry of Object.values(value)) collect(entry, output);
  }
  return output;
};
const clampAtWord = (value, maximum) => {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (text.length <= maximum) return text;
  const candidate = text.slice(0, maximum + 1);
  const boundary = candidate.lastIndexOf(' ');
  return candidate.slice(0, boundary >= Math.floor(maximum * 0.6) ? boundary : maximum)
    .replace(/[,:;\-\s]+$/, '')
    .trim();
};
const faqData = (faq) => faq.length
  ? {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: faq.map((item) => ({
        '@type': 'Question',
        name: item.question,
        acceptedAnswer: { '@type': 'Answer', text: item.answer },
      })),
    }
  : [];

const pageById = new Map(base.pages.map((page) => [page.id, page]));
const sources = Array.isArray(draft.sources) ? draft.sources : [];
const claims = Array.isArray(draft.claims) ? draft.claims : [];
const groundingErrors = [];
if (sources.length < 4) groundingErrors.push('The repaired draft retained fewer than four verified sources.');
for (const source of sources) {
  const page = pageById.get(source?.id);
  if (!page || source?.url !== page.url) {
    groundingErrors.push('A repaired source ID or URL does not match the verified pages.');
    break;
  }
}
const sanitizedSources = sources.map((source) => {
  const page = pageById.get(source?.id);
  return {
    ...source,
    title: String(source?.title || page?.title || ''),
    excerpt:
      typeof source?.excerpt === 'string' && page && containsExcerpt(page.text, source.excerpt)
        ? source.excerpt
        : visibleExcerpt(page?.text),
  };
});
