  const ids = Array.isArray(claim?.sourceIds) ? claim.sourceIds : [];
  const excerpts = Array.isArray(claim?.excerpts) ? claim.excerpts : [];
  if (typeof claim?.sentence !== 'string' || !contains(assembled, claim.sentence)) {
    groundingErrors.push('A claim-ledger sentence is absent from the repaired article.');
  }
  if (claim?.support === 'unsupported') groundingErrors.push('An unsupported claim remains after repair.');
  if (!ids.length || !excerpts.length) groundingErrors.push('A repaired claim has no usable evidence.');
  if (ids.some((id) => !pageById.has(id))) groundingErrors.push('A repaired claim cites an unknown source.');
  if (
    excerpts.some(
      (excerpt) =>
        typeof excerpt !== 'string' ||
        !ids.some((id) => containsExcerpt(pageById.get(id)?.text, excerpt)),
    )
  ) {
    groundingErrors.push('A repaired claim excerpt is absent from its cited source.');
  }
}

