      typeof item.answer === 'string',
  )
  .map((item) => ({ question: item.question, answer: item.answer }));
if (!Array.isArray(draft.faq) || faq.length !== rawFaq.length) {
  groundingErrors.push('Every FAQ entry must have a text question and answer.');
}
