const base = $('Inspect Draft').first().json;
const status = Number($json.statusCode ?? 0);
const body = $json.body ?? $json.data ?? {};
const qualityErrors =
  status >= 200 && status < 300 && Array.isArray(body.errors)
    ? body.errors.map(String)
    : ['The deterministic pre-save quality check was unavailable.'];
const reasons = [
  ...(Array.isArray(base.repairReasons) ? base.repairReasons : []),
  ...(body.valid === true ? [] : qualityErrors),
];
return {
  json: {
    ...base,
    needsRepair: base.needsRepair === true || body.valid !== true,
    repairReasons: [...new Set(reasons)],
    ...(body.qualityReport ? { qualityReport: body.qualityReport } : {}),
  },
};

const base = $('Inspect Repaired Draft').first().json;
const status = Number($json.statusCode ?? 0);
const body = $json.body ?? $json.data ?? {};
const errors =
  status >= 200 && status < 300 && Array.isArray(body.errors)
    ? body.errors.map(String)
    : ['The deterministic pre-save quality check was unavailable.'];
if (body.valid !== true) {
  return {
    json: {
      ...base,
      valid: false,
      failure: {
        code: 'ARTICLE_QUALITY_FAILED',
        message: errors.length
          ? 'The repaired draft still failed its final checks: ' + errors.join(' ')
          : 'The repaired draft did not pass its final checks.',
        details: errors,
      },
    },
  };
}
return {
  json: {
    ...base,
    valid: true,
    needsRepair: false,
    repairReasons: [],
    ...(body.qualityReport ? { qualityReport: body.qualityReport } : {}),
  },
};

const draft = $json.draft;
return {
  json: {
    ...$json,
    saveBody: {
      sessionId: $json.sessionId,
      jobId: $json.jobId,
      context: {
        briefId: $json.context?.brief?.briefId ?? null,
        snapshotId:
          $json.context?.brief?.research?.snapshotId ??
          $json.context?.snapshot?.snapshotId ??
          null,
        memoryJobId:
          $json.context?.brief?.research?.memoryJobId ??
          $json.context?.memory?.jobId ??
